<script module lang="ts">
/**
 * The numbered list of sources a reply cites (`design/components/source-list.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/source-list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/source-list.module.css'

export interface CitationSource {
  title: string
  href: string
  domain?: string
  snippet?: string
}

export interface SourceListProps {
  /**
   * The list's accessible name, such as "Sources" in the app's language.
   */
  label: string
  /**
   * The sources in the order the reply numbers them, rendered as given and never sorted.
   */
  sources: CitationSource[]
}
</script>

<script lang="ts">
let { label: labelOwn, sources }: SourceListProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if sources.length > 0
    }<section class={styles.root} aria-label={label} data-member="source-list"
      ><span class={styles.heading} aria-hidden="true"><Icon name="cite" size="sm" />{label}</span
      ><ol class={styles.list}
        >{#each sources as source, position (position)
          }<li class={styles.item}
            ><span class={styles.index} aria-hidden="true">{position + 1}</span
            ><span class={styles.body}
              ><a class={styles.title} href={source.href} target="_blank" rel="noreferrer"
                >{source.title
                }<span class={styles.glyph}><Icon name="open-external" size="sm" /></span
              ></a
              >{#if source.domain !== undefined
                }<span class={styles.domain}>{source.domain}</span
              >{/if
              }{#if source.snippet !== undefined
                }<span class={styles.snippet}>{source.snippet}</span
              >{/if
            }</span
          ></li
        >{/each
      }</ol
    ></section
  >{/if
}{/if
}{@render joined.end?.()}
